```c
#include "mlmw_test.h"
#include "mlmw/lin.h"
#include <string.h>

#define SUITE agent_lin

ZTEST(SUITE, test_pid_basic)
{
	/* Test basic PID calculation for ID 0 */
	uint8_t pid = mlmw_lin_pid(0);
	EXPECT_EQ(pid, 0x00);

	/* Test basic PID calculation for ID 1 */
	pid = mlmw_lin_pid(1);
	EXPECT_EQ(pid, 0x40);

	/* Test basic PID calculation for ID 63 (0x3F) */
	pid = mlmw_lin_pid(63);
	EXPECT_EQ(pid, 0xC0);
}

ZTEST(SUITE, test_pid_parity_calculation)
{
	/* Test ID 0: 000000 -> P0=0^0^0^0=0, P1=!0^0^0^0=1 -> 0x00 */
	uint8_t pid = mlmw_lin_pid(0);
	EXPECT_EQ(pid, 0x00);

	/* Test ID 1: 000001 -> P0=1^0^0^0=1, P1=!0^0^0^1=0 -> 0x40 */
	pid = mlmw_lin_pid(1);
	EXPECT_EQ(pid, 0x40);

	/* Test ID 2: 000010 -> P0=0^1^0^0=1, P1=!1^0^0^0=1 -> 0x80 */
	pid = mlmw_lin_pid(2);
	EXPECT_EQ(pid, 0x80);

	/* Test ID 3: 000011 -> P0=1^1^0^0=0, P1=!1^0^0^1=1 -> 0xC0 */
	pid = mlmw_lin_pid(3);
	EXPECT_EQ(pid, 0xC0);
}

ZTEST(SUITE, test_pid_boundary_values)
{
	/* Test ID 0x3F (63) - maximum valid ID */
	uint8_t pid = mlmw_lin_pid(0x3F);
	EXPECT_EQ(pid, 0xC0);

	/* Test ID 0x40 - should be masked to 0x3F */
	pid = mlmw_lin_pid(0x40);
	EXPECT_EQ(pid, 0xC0);

	/* Test ID 0x7F - should be masked to 0x3F */
	pid = mlmw_lin_pid(0x7F);
	EXPECT_EQ(pid, 0xC0);
}

ZTEST(SUITE, test_pid_valid_basic)
{
	/* Valid PID for ID 0 */
	uint8_t pid = mlmw_lin_pid(0);
	EXPECT_TRUE(mlmw_lin_pid_valid(pid));

	/* Valid PID for ID 1 */
	pid = mlmw_lin_pid(1);
	EXPECT_TRUE(mlmw_lin_pid_valid(pid));

	/* Invalid PID - wrong parity */
	EXPECT_FALSE(mlmw_lin_pid_valid(0x01)); /* Should be 0x00 for ID 0 */
	EXPECT_FALSE(mlmw_lin_pid_valid(0x41)); /* Should be 0x40 for ID 1 */
}

ZTEST(SUITE, test_pid_valid_boundary)
{
	/* Test valid PIDs at boundaries */
	uint8_t pid = mlmw_lin_pid(0);
	EXPECT_TRUE(mlmw_lin_pid_valid(pid));

	pid = mlmw_lin_pid(63);
	EXPECT_TRUE(mlmw_lin_pid_valid(pid));

	/* Test invalid PIDs */
	EXPECT_FALSE(mlmw_lin_pid_valid(0x01));
	EXPECT_FALSE(mlmw_lin_pid_valid(0xC1));
}

ZTEST(SUITE, test_checksum_classic)
{
	uint8_t data[] = {0x01, 0x02, 0x03};
	uint8_t checksum;

	/* Test classic checksum with ID 0 */
	checksum = mlmw_lin_checksum(0x00, data, 3, false);
	EXPECT_EQ(checksum, 0xF9); /* (0x01 + 0x02 + 0x03) = 0x06, ~0x06 = 0xF9 */

	/* Test classic checksum with ID 1 */
	checksum = mlmw_lin_checksum(0x40, data, 3, false);
	EXPECT_EQ(checksum, 0xF9); /* Same result as above */
}

ZTEST(SUITE, test_checksum_enhanced)
{
	uint8_t data[] = {0x01, 0x02, 0x03};
	uint8_t checksum;

	/* Test enhanced checksum with ID 0x3C (master request) - should use classic */
	checksum = mlmw_lin_checksum(0x3C, data, 3, true);
	EXPECT_EQ(checksum, 0xF9); /* Same as classic */

	/* Test enhanced checksum with ID 0x3D (slave response) - should use classic */
	checksum = mlmw_lin_checksum(0x3D, data, 3, true);
	EXPECT_EQ(checksum, 0xF9); /* Same as classic */

	/* Test enhanced checksum with ID 0x01 - should include PID */
	checksum = mlmw_lin_checksum(0x41, data, 3, true);
	EXPECT_EQ(checksum, 0xF8); /* (0x41 + 0x01 + 0x02 + 0x03) = 0x47, ~0x47 = 0xB8 */
}

ZTEST(SUITE, test_checksum_zero_data)
{
	uint8_t checksum;

	/* Test with zero length data */
	checksum = mlmw_lin_checksum(0x00, NULL, 0, false);
	EXPECT_EQ(checksum, 0xFF); /* ~0 = 0xFF */

	checksum = mlmw_lin_checksum(0x40, NULL, 0, true);
	EXPECT_EQ(checksum, 0xFF); /* Same result */
}

ZTEST(SUITE, test_checksum_carry_wrap)
{
	uint8_t data[] = {0xFF, 0xFF};
	uint8_t checksum;

	/* Test carry wraparound */
	checksum = mlmw_lin_checksum(0x00, data, 2, false);
	EXPECT_EQ(checksum, 0x01); /* (0xFF + 0xFF) = 0x1FE, wrap to 0xFE, ~0xFE = 0x01 */
}

ZTEST(SUITE, test_checksum_enhanced_with_pid)
{
	uint8_t data[] = {0x01, 0x02};
	uint8_t checksum;

	/* Test enhanced checksum with ID 0x05 (not master or slave) - should include PID */
	checksum = mlmw_lin_checksum(0x45, data, 2, true);
	EXPECT_EQ(checksum, 0xF7); /* (0x45 + 0x01 + 0x02) = 0x48, ~0x48 = 0xB7 */
}

ZTEST(SUITE, test_checksum_edge_cases)
{
	uint8_t data[] = {0x00};
	uint8_t checksum;

	/* Test with single zero byte */
	checksum = mlmw_lin_checksum(0x00, data, 1, false);
	EXPECT_EQ(checksum, 0xFF); /* ~0x00 = 0xFF */

	/* Test with single non-zero byte */
	checksum = mlmw_lin_checksum(0x00, data, 1, true);
	EXPECT_EQ(checksum, 0xFF); /* Same result */
}

ZTEST_SUITE(SUITE, NULL, NULL, NULL, NULL, NULL);
